import {REGIONS,LARGE_ENEMIES} from './engine.js';
// Canvas compatibility view; runs the same simulation, including every campaign mechanic.
export class SoftwareView{
 constructor(canvas,settings){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.settings=settings;this.resize();}
 resize(){this.canvas.width=innerWidth;this.canvas.height=innerHeight;this.w=innerWidth;this.h=innerHeight;}
 quality(s){this.settings=s;}effect(){}
 render(b,dt,screen){const c=this.ctx,w=this.w,h=this.h,r=REGIONS[Math.floor(b.stage/2)];c.fillStyle=r.sky;c.fillRect(0,0,w,h);c.fillStyle=r.ground;c.fillRect(0,h*.22,w,h);const project=(x,z)=>{const d=35-z;const scale=Math.min(w/19,h/24)*35/d;return [w/2+x*scale,h*.82+z*scale*.4,scale];};c.fillStyle=r.road;c.beginPath();c.moveTo(w*.43,h*.22);c.lineTo(w*.57,h*.22);c.lineTo(w*1.3,h);c.lineTo(-w*.3,h);c.fill();
 if(screen!=='battle'){const size=Math.min(w*.6,h*.52),x=w*.5,y=h*.48;c.fillStyle='#d3c7a8';c.fillRect(x-size*.3,y-size*.3,size*.6,size*.4);for(const dx of [-.32,.32]){c.fillRect(x+dx*size-size*.08,y-size*.4,size*.16,size*.56);c.fillStyle='#327888';c.beginPath();c.moveTo(x+dx*size-size*.12,y-size*.4);c.lineTo(x+dx*size,y-size*.62);c.lineTo(x+dx*size+size*.12,y-size*.4);c.fill();c.fillStyle='#d3c7a8';}c.fillStyle='#344c50';c.fillRect(x-size*.06,y-size*.08,size*.12,size*.18);return;}
 const soldier=(x,z,enemy,i,scale=1)=>{const [px,py,unit]=project(x,z),s=unit*scale;const t=Math.sin(b.time*8+i)*s*.2;c.strokeStyle='#314e5a';c.lineWidth=Math.max(2,s*.13);c.beginPath();c.moveTo(px-s*.1,py-s*.4);c.lineTo(px-s*.12+t,py);c.moveTo(px+s*.1,py-s*.4);c.lineTo(px+s*.12-t,py);c.stroke();c.fillStyle=enemy?'#af5655':'#329bb3';c.fillRect(px-s*.22,py-s*1.1,s*.44,s*.65);c.fillStyle='#e1c095';c.beginPath();c.arc(px,py-s*1.3,s*.18,0,7);c.fill();c.fillStyle='#bdd3d1';c.fillRect(px-s*.21,py-s*1.53,s*.42,s*.15);c.strokeStyle='#dbbf81';c.lineWidth=2;c.beginPath();c.moveTo(px+s*.28,py-s*.55);c.lineTo(px+s*.32,py-s*1.5);c.stroke();};
 for(const e of [...b.entities].sort((a,b)=>a.z-b.z)){if(['gate','target','crate','treasure'].includes(e.type)){const [x,y,s]=project(e.x,e.z);c.fillStyle=e.type==='gate'?(e.op==='−'?'#b65458':'#2d8e78'):'#ae8740';c.fillRect(x-s*2,y-s*3,s*4,s*2);c.fillStyle='#fff2cf';c.font=`bold ${Math.max(12,s*.8)}px Georgia`;c.textAlign='center';c.fillText(e.type==='gate'?e.op+e.value:e.type==='target'?'+10':e.type==='crate'?'ATK':'+35',x,y-s*1.6);}else if(LARGE_ENEMIES.has(e.type)){const scale=e.type==='ogre'?2.6:e.type==='champion'?2.25:2.05;soldier(e.x,e.z,true,e.id,scale);const [x,y,u]=project(e.x,e.z);const size=u*scale,ratio=Math.max(0,e.hp/e.maxHp),width=Math.max(48,u*2.8),barY=y-size*2.02;
 c.fillStyle=e.flash>0?'#fff0b7':e.type==='ogre'?'#81a56c':e.type==='brute'?'#a67754':'#7e698f';c.fillRect(x-size*.23,y-size*1.1,size*.46,size*.65);c.fillStyle='#f2cf86';for(const side of [-1,1]){c.beginPath();c.moveTo(x+side*size*.18,y-size*1.45);c.lineTo(x+side*size*.3,y-size*1.95);c.lineTo(x+side*size*.06,y-size*1.55);c.fill();}c.fillStyle='#253a43';c.fillRect(x-width/2-2,barY-2,width+4,10);c.fillStyle=e.flash>0?'#fff0b7':ratio<.3?'#f07863':'#edb764';c.fillRect(x-width/2,barY,width*ratio,6);c.fillStyle='#fff0be';c.textAlign='center';c.font=`bold ${Math.max(8,u*.35)}px system-ui`;c.fillText(e.type.toUpperCase(),x,barY-5);
 }else soldier(e.x,e.z,true,e.id);}
 if(b.boss){const e=b.boss,[x,y,s]=project(e.x,e.z);c.fillStyle=['#638655','#8a849c','#607f87','#93c8d7','#a35c50','#786392'][e.index];c.fillRect(x-2*s,y-6*s,4*s,5*s);c.beginPath();c.arc(x,y-6*s,s*1.4,0,7);c.fill();c.fillStyle='#ffe0a0';c.beginPath();c.arc(project(e.weakX,e.z)[0],y-s*3.5,s*.5,0,7);c.fill();c.fillStyle='#f8d071';for(const side of [-1,1]){c.beginPath();c.moveTo(x+side*s,y-s*6.5);c.lineTo(x+side*1.7*s,y-s*8.4);c.lineTo(x+side*s*.5,y-s*7);c.fill();}}
 for(const a of b.hazards){const [x,y,s]=project(a.x,2);c.fillStyle=a.triggered?'#ffbc6e':'#d56565';c.globalAlpha=.6;c.fillRect(x-s*a.width/2,y-s*2,s*a.width,s*3);c.globalAlpha=1;}
 for(let i=0;i<Math.min(b.army,70);i++)soldier(b.x+(i%7-3)*.6,2+Math.floor(i/7)*.65,false,i);
 c.strokeStyle='#fff2b5';c.lineWidth=2.4;for(const a of b.shots){const [x,y,s]=project(a.x,a.z);c.beginPath();c.moveTo(x,y-s);c.lineTo(x,y-s*2.2);c.stroke();}for(const d of b.drops){const [x,y,s]=project(d.x,d.z);c.fillStyle=d.type==='gold'?'#ffda60':'#8ce8bd';c.beginPath();c.arc(x,y-s,s*.2,0,7);c.fill();}}
}
